    if not ns.Places[key] then ns.Places[key] = p end
end
for id, q in pairs(quests) do
    if not ns.Quests[id] then ns.Quests[id] = q end
end

-- Ancestros del Festival Lunar que estan dentro de una mazmorra: Wowhead no les da
-- coordenadas, asi que su sitio es la entrada de la mazmorra (puesto a mano; el ala
-- de La Masacre de Mistwalker sin confirmar).
ns.EventDungeon = { [8619] = "BRD", [8635] = "MARA", [8644] = "LBRS", [8676] = "ZF", [8685] = "DM_E",
    [8713] = "ST", [8714] = "SCHOLO", [8727] = "STRAT_LIVE" }
for id, key in pairs(ns.EventDungeon) do
    local d
    for _, dungeon in ipairs(ns.Dungeons) do if dungeon.key == key then d = dungeon end end
    local q = ns.Quests[id]
    local p = d and d.entrance and q and q.starts and ns.Places[q.starts[1]]
    if p and not p.mapID then
        p.mapID, p.x, p.y, p.inside = d.entrance.mapID, d.entrance.x, d.entrance.y, true
    end
end
